import * as THREE from './vendor/three.module.js';
import {elevation} from './terrain.js';
const material=(color,extras={})=>new THREE.MeshStandardMaterial({color,roughness:.85,...extras});
let seed=1042;function random(){seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;}
function canvasTexture(size,paint){const c=document.createElement('canvas');c.width=c.height=size;paint(c.getContext('2d'),size);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=8;return t;}
const grassTexture=canvasTexture(512,(ctx,n)=>{ctx.fillStyle='#b6c4a0';ctx.fillRect(0,0,n,n);for(let i=0;i<42000;i++){const x=random()*n,y=random()*n;ctx.strokeStyle=random()>.5?'rgba(45,70,25,.15)':'rgba(255,255,210,.22)';ctx.lineWidth=.4+random();ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+random()*2-1,y-2-random()*4);ctx.stroke();}});
const sandTexture=canvasTexture(256,(ctx,n)=>{ctx.fillStyle='#eedcc0';ctx.fillRect(0,0,n,n);for(let i=0;i<11000;i++){ctx.fillStyle=random()>.5?'#d9c6a6':'#f8eddb';ctx.fillRect(random()*n,random()*n,.8,.8);}});
const barkTexture=canvasTexture(256,(ctx,n)=>{ctx.fillStyle='#655447';ctx.fillRect(0,0,n,n);for(let i=0;i<300;i++){ctx.strokeStyle=random()>.5?'#786250':'#4d4136';const x=random()*n;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+random()*8,n);ctx.stroke();}});
const waterNormals=canvasTexture(256,(ctx,n)=>{const data=ctx.createImageData(n,n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4;data.data[i]=128+Math.sin(x*.17+y*.09)*22+Math.sin(y*.19)*12;data.data[i+1]=128+Math.cos(y*.21+x*.07)*22;data.data[i+2]=248;data.data[i+3]=255;}ctx.putImageData(data,0,0);});waterNormals.colorSpace=THREE.NoColorSpace;waterNormals.repeat.set(30,30);
const leafTexture=canvasTexture(256,(ctx,n)=>{ctx.fillStyle='#e0e7c8';ctx.fillRect(0,0,n,n);for(let i=0;i<2500;i++){ctx.fillStyle=['#c5d3a8','#a8bf89','#f0efd0'][i%3];ctx.beginPath();ctx.ellipse(random()*n,random()*n,1+random()*2,2+random()*4,random()*Math.PI,0,Math.PI*2);ctx.fill();}});
const groundMap=grassTexture.clone();groundMap.repeat.set(80,155);
const greenMap=grassTexture.clone();greenMap.repeat.set(8,8);
const sandMap=sandTexture.clone();sandMap.repeat.set(9,9);
export const materials={grass:material('#607544',{map:groundMap}),fair:material('#638742',{map:grassTexture}),green:material('#75a650',{map:greenMap}),sand:material('#e5d2b0',{map:sandMap}),trunk:material('#8e8170',{map:barkTexture}),leaf:material('#c5d4b5',{map:leafTexture}),white:material('#f5f3e6'),dark:material('#19493f'),tire:material('#252a28'),skin:material('#d0a07c'),shirt:material('#f6f3e8'),pants:material('#30443a'),water:material('#297e8c',{normalMap:waterNormals,normalScale:new THREE.Vector2(.7,.7),roughness:.19,metalness:.3}),path:material('#b3ae97',{map:sandMap}),steel:material('#acb4b6',{metalness:.8,roughness:.25})};
function add(parent,geo,mat,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
function sphere(parent,mat,x,y,z,sx,sy,sz){const m=add(parent,new THREE.SphereGeometry(1,20,14),mat,x,y,z);m.scale.set(sx,sy,sz);return m;}
function cylinder(parent,mat,x,y,z,r1,r2,len){return add(parent,new THREE.CylinderGeometry(r1,r2,len,12),mat,x,y,z);}
function roundedBox(parent,mat,x,y,z,w,h,d){const geo=new THREE.BoxGeometry(w,h,d,4,4,4);const p=geo.attributes.position,half=new THREE.Vector3(w/2,h/2,d/2),v=new THREE.Vector3(),core=new THREE.Vector3();const r=Math.min(w,h,d)*.2;for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i);core.copy(v).clamp(half.clone().negate().addScalar(r),half.clone().addScalar(-r));v.sub(core).normalize().multiplyScalar(r).add(core);p.setXYZ(i,v.x,v.y,v.z);}geo.computeVertexNormals();return add(parent,geo,mat,x,y,z);}
export function atmosphere(scene){
 const sky=new THREE.Mesh(new THREE.SphereGeometry(900,32,16),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{top:{value:new THREE.Color('#438fca')},bottom:{value:new THREE.Color('#b8dce5')}},vertexShader:'varying vec3 vWorld; void main(){vWorld=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'uniform vec3 top;uniform vec3 bottom;varying vec3 vWorld;void main(){float h=clamp(normalize(vWorld).y*.85+.12,0.0,1.0);gl_FragColor=vec4(mix(bottom,top,pow(h,.65)),1.0);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}',fog:false}));scene.add(sky);
 const cloudMap=canvasTexture(128,(ctx,n)=>{const g=ctx.createRadialGradient(n/2,n/2,0,n/2,n/2,n/2);g.addColorStop(0,'rgba(255,255,255,.85)');g.addColorStop(.5,'rgba(255,255,255,.6)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,n,n);});
 const cloudMat=new THREE.SpriteMaterial({map:cloudMap,transparent:true,depthWrite:false,opacity:.42,fog:true});for(let i=0;i<32;i++){const sprite=new THREE.Sprite(cloudMat);sprite.position.set(-430+random()*950,75+random()*85,-150-random()*450);sprite.scale.set(70+random()*100,20+random()*35,1);scene.add(sprite);}
 const glowMap=canvasTexture(128,(ctx,n)=>{const g=ctx.createRadialGradient(64,64,1,64,64,64);g.addColorStop(0,'rgba(255,247,210,1)');g.addColorStop(.1,'rgba(255,233,185,.8)');g.addColorStop(.35,'rgba(255,215,155,.16)');g.addColorStop(1,'rgba(255,215,155,0)');ctx.fillStyle=g;ctx.fillRect(0,0,n,n);});const glow=new THREE.Sprite(new THREE.SpriteMaterial({map:glowMap,transparent:true,depthWrite:false,fog:false}));glow.position.set(-260,165,-480);glow.scale.set(155,155,1);scene.add(glow);
}
export function makeTree(parent,x,z,index){
 const g=new THREE.Group();g.userData.isTree=true;g.position.set(x,0,z);parent.add(g);const scale=.8+(index%7)*.09;g.scale.setScalar(scale);cylinder(g,materials.trunk,0,3,0,.24,.5,6);
 for(let i=0;i<5;i++){const a=i*2.4,b=cylinder(g,materials.trunk,Math.sin(a)*.6,4.4+i*.35,Math.cos(a)*.6,.08,.2,2.7);b.rotation.z=Math.sin(a)*.65;b.rotation.x=Math.cos(a)*.65;}
 const leafGeo=new THREE.IcosahedronGeometry(1,2),leaves=new THREE.InstancedMesh(leafGeo,materials.leaf,42);const dummy=new THREE.Object3D();for(let i=0;i<42;i++){const a=i*2.399,r=Math.sqrt(random())*3.5;dummy.position.set(Math.cos(a)*r,5.8+random()*3.8,Math.sin(a)*r);dummy.scale.set(1.4+random(),1.2+random(),1.4+random());dummy.updateMatrix();leaves.setMatrixAt(i,dummy.matrix);leaves.setColorAt(i,new THREE.Color().setHSL(.25+random()*.05,.28+random()*.16,.18+random()*.09));}leaves.castShadow=true;leaves.receiveShadow=true;const lod=new THREE.LOD();lod.addLevel(leaves,0);const distant=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,1),materials.leaf,42);distant.instanceMatrix.copy(leaves.instanceMatrix);distant.instanceColor=leaves.instanceColor.clone();distant.castShadow=distant.receiveShadow=true;lod.addLevel(distant,65);g.add(lod);
}
export function makeGolfer(scene){
 const g=new THREE.Group();scene.add(g);const legs=[];const arms=[];
 sphere(g,materials.shirt,0,1.75,0,.42,.58,.27);cylinder(g,materials.dark,0,1.22,0,.33,.33,.09);sphere(g,materials.skin,0,2.58,0,.27,.34,.25);cylinder(g,materials.skin,0,2.25,0,.13,.13,.22);
 const cap=sphere(g,materials.white,0,2.81,.02,.29,.15,.28);roundedBox(g,materials.white,0,2.78,-.23,.42,.045,.3);roundedBox(g,materials.dark,0,2.56,-.235,.4,.08,.035);
 for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.19,1.18,0);g.add(leg);cylinder(leg,materials.pants,0,-.44,0,.145,.11,.88);sphere(leg,materials.white,0,-1.04,-.09,.17,.1,.3);legs.push(leg);const arm=new THREE.Group();arm.position.set(side*.36,2.03,0);g.add(arm);sphere(arm,materials.shirt,side*.04,-.16,0,.17,.25,.18);cylinder(arm,materials.skin,side*.05,-.53,0,.09,.075,.53);sphere(arm,materials.skin,side*.05,-.82,0,.085,.1,.085);arms.push(arm);}
 const club=new THREE.Group();g.add(club);club.position.set(.55,1.1,-.1);const shaft=cylinder(club,materials.steel,0,-.3,0,.018,.018,1.55);shaft.rotation.z=-.14;roundedBox(club,materials.dark,.1,-1.07,-.03,.27,.13,.14);return {group:g,legs,arms,club};
}
export function makeCart(scene){
 const g=new THREE.Group();scene.add(g);const wheels=[];roundedBox(g,materials.white,0,.74,0,2.05,.38,3.2);roundedBox(g,materials.dark,0,1.03,-1.03,1.98,.65,1.12);roundedBox(g,materials.white,0,2.95,0,2.25,.16,3.5);
 roundedBox(g,materials.sand,0,1.1,.5,1.8,.3,.9);roundedBox(g,materials.sand,0,1.52,.95,1.8,.72,.22);
 const glass=new THREE.MeshPhysicalMaterial({color:'#b8dbd9',transparent:true,opacity:.19,roughness:.08,metalness:.15,side:THREE.DoubleSide});add(g,new THREE.PlaneGeometry(1.72,1.25),glass,0,2.05,-1.18);
 for(const x of [-.91,.91])for(const z of [-1.2,1.2]){cylinder(g,materials.steel,x,1.98,z,.035,.035,1.9);const wheel=cylinder(g,materials.tire,x*1.2,.45,z,.43,.43,.3);wheel.rotation.z=Math.PI/2;const hub=cylinder(g,materials.steel,x*1.22,.45,z,.23,.23,.32);hub.rotation.z=Math.PI/2;wheels.push(wheel);const tread=new THREE.Mesh(new THREE.TorusGeometry(.43,.06,6,24),materials.tire);tread.rotation.y=Math.PI/2;tread.position.set(x*1.2,.45,z);g.add(tread);}
 const headlight=new THREE.MeshStandardMaterial({color:'#fff5d7',emissive:'#fff0ca',emissiveIntensity:.4});for(const x of [-.7,.7])roundedBox(g,headlight,x,1.04,-1.6,.32,.17,.035);
 roundedBox(g,materials.steel,0,.58,-1.68,1.8,.12,.12);roundedBox(g,materials.dark,0,.85,1.64,1.8,.1,.15);
 const steering=add(g,new THREE.TorusGeometry(.29,.027,8,24),materials.tire,-.47,1.65,-.55);steering.rotation.x=-.7;cylinder(g,materials.steel,-.47,1.36,-.43,.028,.028,.5);
 const bag=cylinder(g,materials.dark,.5,1.45,1.5,.27,.24,1.15);bag.rotation.x=.16;for(let i=0;i<6;i++){cylinder(g,materials.steel,.35+(i%3)*.11,2.12+(i%2)*.13,1.48+(i%2)*.12,.018,.018,.85);roundedBox(g,materials.steel,.35+(i%3)*.11,2.55+(i%2)*.13,1.48+(i%2)*.12,.16,.09,.08);}return {group:g,wheels};
}
export function landscape(parent,h,fairCenter,terrain){
 // Smooth dunes and distant headlands replace the geometric mountain wall.
 const geo=new THREE.PlaneGeometry(850,900,100,100);geo.rotateX(-Math.PI/2);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i)-100,z=p.getZ(i)-240;const outside=Math.max(0,Math.min(1,(Math.abs(x)-112)/80));const distant=Math.max(0,Math.min(1,(-z-h.length-55)/120));const height=(outside+distant)*(.5+.5*Math.sin(x*.017+z*.012))*(12+18*Math.sin(z*.009)**2);const coastalFade=1-THREE.MathUtils.smoothstep(x,65,112);p.setXYZ(i,x,elevation(x,z,h)-.4+height*coastalFade-THREE.MathUtils.smoothstep(x,100,130)*2,z);}geo.computeVertexNormals();add(parent,geo,material('#718168',{map:groundMap}));
 const pathPoints=[];for(let i=0;i<=45;i++){const z=25-i*(h.length+60)/45;pathPoints.push(new THREE.Vector3(fairCenter(z)-32,.035,z));}const pathGeo=new THREE.BufferGeometry(),verts=[],uv=[],ind=[];for(let i=0;i<pathPoints.length;i++){const p=pathPoints[i];verts.push(p.x-1.7,p.y,p.z,p.x+1.7,p.y,p.z);uv.push(0,i/3,1,i/3);if(i<pathPoints.length-1){const n=i*2;ind.push(n,n+1,n+2,n+1,n+3,n+2);}}pathGeo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));pathGeo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));pathGeo.setIndex(ind);pathGeo.computeVertexNormals();const pathMesh=add(parent,pathGeo,materials.path);pathMesh.userData.surfaceDetail=true;
 // Bunker rake lines and raised grass lips give the sand a defined edge.
 for(const[x,z,rx,rz]of h.sand){for(let i=-3;i<=3;i++){const curve=new THREE.EllipseCurve(0,0,rx*.8,rz*.8,i*.12+.2,i*.12+2.5,false);const points=curve.getPoints(45).map(p=>new THREE.Vector3(x+p.x,.074,z+p.y));const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:'#c7b492',transparent:true,opacity:.45}));line.userData.surfaceDetail=true;parent.add(line);}}
 // A small clubhouse anchors the first tee.
 const house=new THREE.Group();parent.add(house);house.position.set(-52,0,22);roundedBox(house,material('#eee4cd'),0,3,0,17,6,12);const roof=add(house,new THREE.CylinderGeometry(11,11,2,4),material('#56615d'),0,6.8,0);roof.rotation.y=Math.PI/4;roof.scale.z=.75;for(let i=-2;i<=2;i++){roundedBox(house,materials.dark,i*3,3,-6.03,1.7,2.4,.06);cylinder(house,materials.white,i*3,2.6,-8,.14,.14,5.2);}roundedBox(house,materials.white,0,5.3,-7,17,.3,4);
}
export function animateWater(time){waterNormals.offset.set(time*.000007,time*.000012);}
export function golfBallMaterial(){
 const bump=canvasTexture(512,(ctx,n)=>{ctx.fillStyle='#aaa';ctx.fillRect(0,0,n,n);for(let row=1;row<22;row++)for(let col=0;col<36;col++){const x=(col+(row%2)*.5)*n/36,y=row*n/22;const g=ctx.createRadialGradient(x,y,1,x,y,5);g.addColorStop(0,'#555');g.addColorStop(.7,'#888');g.addColorStop(1,'#aaa');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();}});bump.colorSpace=THREE.NoColorSpace;
 const map=canvasTexture(512,(ctx,n)=>{ctx.fillStyle='#fffef4';ctx.fillRect(0,0,n,n);ctx.strokeStyle='#245542';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(220,245);ctx.lineTo(300,245);ctx.stroke();ctx.font='bold 13px sans-serif';ctx.fillStyle='#245542';ctx.fillText('FAIRWAY',227,265);});return material('#ffffff',{map,bumpMap:bump,bumpScale:.025,roughness:.35});
}
